<h2><?=h($title)?></h2><div class="table-card table-responsive"><table class="table"><tr><th>订单号</th><th>标题</th><th>金额</th><th>状态</th><th></th></tr><?php foreach ($orders as $o): ?><tr><td><?=h($o['order_no'])?></td><td><?=h($o['title'])?></td><td><?=money($o['pay_amount'])?></td><td><?=order_status_badge($o)?></td><td><a href="<?=h(url_to('index/order/detail', ['id' => $o['id']]))?>">详情</a><?php if ($o['status'] === 'unpaid'): ?> <a href="<?=h(url_to('index/pay/index', ['id' => $o['id']]))?>">支付</a><?php endif; ?></td></tr><?php endforeach; ?></table></div>
